/// <summary>
/// METInventInventoryDataServiceInstrumentationActivities
/// </summary>
internal final class METInventInventoryDataServiceInstrumentationActivities
{
    private const str ActivityNamePrefix = 'InventoryVisibility.';
    private METInventInstrumentationLogger logger;

}

Method.Source:
/// <summary>
/// new constructor
/// </summary>
/// <param name = "_logger">METInventInstrumentationLogger</param>
private void new(METInventInstrumentationLogger _logger)
{
    logger = _logger;
}

/// <summary>
/// logger constructor
/// </summary>
/// <param name = "_logger">METInventInstrumentationLogger</param>
/// <returns>METInventInventoryDataServiceInstrumentationActivities</returns>
public static METInventInventoryDataServiceInstrumentationActivities newFromLogger(METInventInstrumentationLogger _logger)
{
    return new METInventInventoryDataServiceInstrumentationActivities(_logger);
}

